from backend import Backend, Duplicate
from service import save
backend = Backend()
created = save(backend, 'key', 'original')['created']
assert created is None
print('Direct backend creation: created is None')
try:
    save(backend, 'key', 'replacement')
except Duplicate:
    print('Direct backend duplicate: Duplicate propagates')
else:
    raise AssertionError('Expected Duplicate')
assert backend.rows['key'] == 'original'
print('Original value preserved')
class Offline:
    def put(self, key, value):
        raise OSError('offline')
try:
    save(Offline(), 'key', 'value')
except OSError:
    print('Direct backend operational failure: OSError propagates')
else:
    raise AssertionError('Expected OSError')
PY"

